import { edit_user_app_access } from "@/graphql/mutations.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import DeleteuserAdmins from "./DeleteuserAdmins.vue";
import { list_user_app_subscribers } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    DeleteuserAdmins
  },
  mixins: [get_all_org_users],
  props: {
    userappAdmins: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      SnackBarComponent: {},
      componentCheck: 0,
      onBoardDialog: false,
      deleteadmins: false,
      loading: false,
      searchF: "",
      headers: [{
        title: "User",
        value: "client_id",
        sortable: true
      }, {
        title: "Actions",
        value: "action",
        sortable: false,
        align: "center"
      }],
      tableData: [],
      height: 0,
      tableLoading: false,
      adminitems: {},
      approvalType: "",
      admincheck: false,
      selectTeam: "",
      formDetails: {},
      formViewDailog: false,
      fixed: true,
      actionItem: "",
      viewAction: "Inititaie",
      useraccess: "ALL_USERS",
      userArray: []
    };
  },
  watch: {
    userappAdmins: {
      async handler() {
        this.height = window.innerHeight - 290;
        this.useraccess = this.rowInfo.user_access == null ? "ALL_USERS" : this.rowInfo.user_access;
        this.selectTeam = "";
        this.$store.commit("Setnamesearch", "");
        await this.adminslist();
        await this.get_all_org_users();
        await this.fetch_details();
      },
      immediate: true
    },
    tableData: {
      handler(newVal) {
        if (newVal && newVal.length > 1) {
          this.useraccess = "RESTRICTED_USERS";
        }
      },
      immediate: true
    }
  },
  // created() {
  //    console.log(this.$store.getters.GetAppDetails.dashboard_id);

  // },
  methods: {
    async add_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(edit_user_app_access, {
            input: {
              user_access: this.useraccess,
              action_type: "ADD",
              user_email_id: this.useraccess == "ALL_USERS" ? undefined : this.selectTeam.user_id,
              dashboard_id: this.rowInfo.dashboard_id
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.edit_user_app_access);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.selectTeam = "";
            this.$refs.form.reset();
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.adminslist();
            this.useraccess = "ALL_USERS";
          } else {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
          }
        } catch (error) {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: error.errors[0].message,
            timeout: 5000,
            Top: true
          };
          this.loading = false;
        }
      }
    },
    fetch_details() {
      // Clear the array first to prevent duplicates
      this.userArray = [];
      const seenUserIds = new Set();
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT" && !seenUserIds.has(element.user_email_id)) {
          seenUserIds.add(element.user_email_id);
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    close_dialog() {
      this.useraccess = "ALL_USERS";
      this.selectTeam = "";
      this.$emit("clicked", 0);
    },
    async adminslist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_user_app_subscribers, {
          input: {
            dashboard_id: this.rowInfo.dashboard_id
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        if (result && result.data && result.data.list_user_app_subscribers) {
          var response = JSON.parse(result.data.list_user_app_subscribers);
          this.tableData = response.data || [];
          this.admincheck = response.all_users || false;
        } else {
          this.tableData = [];
          this.admincheck = false;
        }

        // console.log(response);
        // console.log(response);
      } catch (error) {
        // console.log(error);
        this.tableLoading = false;
        this.tableData = [];
        this.admincheck = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    delete_admins(item) {
      this.adminitems = item;
      this.componentCheck = 2;
      this.deleteadmins = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.deleteadmins = false;
      this.adminslist();
    }
  }
};
